                  )}
                </div>
                <div className="flex items-center gap-1.5 shrink-0 ml-2">
                  {showSaveAgent && (
                    <button
                      onClick={() => openSaveAgent(s, key)}
                      className="flex items-center gap-1 text-[11px] px-2.5 py-1 rounded-md font-medium bg-purple-muted text-purple hover:opacity-80 transition-all"
                    >
                      Save as Agent
                    </button>
                  )}
                  {(showApply || applied) && (
                    <button
                      onClick={() => handleApplyFile(s, key)}
                      disabled={applied || applying}
                      className={`flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-md font-medium transition-all ${
                        applied
                          ? 'bg-green-muted text-green cursor-default'
                          : 'bg-accent text-white hover:bg-accent-hover disabled:opacity-50'
                      }`}
                    >
                      {applying ? (
                        <RefreshCw className="w-3 h-3 animate-spin" />
                      ) : applied ? (
                        <><CheckCircle className="w-3 h-3" /> Applied</>
                      ) : (
                        'Apply to file'
                      )}
                    </button>
                  )}
                </div>
              </div>
              <pre className="px-3.5 py-2.5 text-[11px] font-mono text-text-secondary overflow-x-auto max-h-40 whitespace-pre-wrap break-words leading-relaxed">
                {s.content.slice(0, 800)}{s.content.length > 800 ? '\n…' : ''}
              </pre>
              <div className="px-3.5 pb-2">
                <p className="text-[10px] font-mono text-text-muted truncate">{s.path}</p>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

