import { useState } from 'react'
import { Copy, Check, Terminal } from 'lucide-react'

// ─── Markdown Tokenizer ───────────────────────────────────────────────────────

type Token =
  | { type: 'h1' | 'h2' | 'h3' | 'h4'; text: string }
  | { type: 'hr' }
  | { type: 'code'; lang: string; text: string }
  | { type: 'table'; headers: string[]; rows: string[][] }
  | { type: 'ul'; items: string[] }
  | { type: 'ol'; items: string[]; start: number }
  | { type: 'paragraph'; text: string }

function tokenize(md: string): Token[] {
  const tokens: Token[] = []
  const lines = md.split('\n')
  let i = 0

  while (i < lines.length) {
    const line = lines[i]

    // Blank
    if (line.trim() === '') { i++; continue }

    // Headings
    const hm = line.match(/^(#{1,4})\s+(.+)$/)
    if (hm) {
      const level = hm[1].length
      const rawText = hm[2].replace(/\s+#+\s*$/, '')
      const type = (['h1', 'h2', 'h3', 'h4'] as const)[level - 1]
      tokens.push({ type, text: rawText })
      i++; continue
    }

    // Horizontal rule
    if (line.match(/^[-*_]{3,}\s*$/)) {
      tokens.push({ type: 'hr' })
      i++; continue
    }

    // Fenced code block
    if (line.match(/^```/)) {
      const lang = line.slice(3).trim()
      const codeLines: string[] = []
      i++
      while (i < lines.length && !lines[i].match(/^```\s*$/)) {
        codeLines.push(lines[i])
        i++
      }
      i++ // skip closing ```
      tokens.push({ type: 'code', lang, text: codeLines.join('\n') })
      continue
    }

    // Table
    if (line.startsWith('|')) {
      const tableLines: string[] = []
      while (i < lines.length && lines[i].trimStart().startsWith('|')) {
        tableLines.push(lines[i])
        i++
      }
      if (tableLines.length >= 2) {
        const parseRow = (r: string) =>
          r.split('|').slice(1, -1).map(c => c.trim()).filter((_, idx, arr) => idx < arr.length)
        const headers = parseRow(tableLines[0])
        const rows: string[][] = []
        for (let j = 2; j < tableLines.length; j++) {
          rows.push(parseRow(tableLines[j]))
        }
        tokens.push({ type: 'table', headers, rows })
      }
      continue
    }

    // Unordered list
    if (line.match(/^(\s*)[-*+]\s/)) {
      const items: string[] = []
      while (i < lines.length && lines[i].match(/^(\s*)[-*+]\s/)) {
        items.push(lines[i].replace(/^(\s*)[-*+]\s/, ''))
        i++
      }
      tokens.push({ type: 'ul', items })
      continue
    }

    // Ordered list
    if (line.match(/^\d+\.\s/)) {
      const items: string[] = []
      const start = parseInt(line.match(/^(\d+)/)?.[1] ?? '1', 10)
      while (i < lines.length && lines[i].match(/^\d+\.\s/)) {
        items.push(lines[i].replace(/^\d+\.\s/, ''))
        i++
      }
      tokens.push({ type: 'ol', items, start })
      continue
    }

    // Paragraph (collect consecutive non-special lines)
    const paraLines: string[] = []
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !lines[i].match(/^#{1,4}\s/) &&
      !lines[i].match(/^```/) &&
      !lines[i].trimStart().startsWith('|') &&
      !lines[i].match(/^(\s*)[-*+]\s/) &&
      !lines[i].match(/^\d+\.\s/) &&
      !lines[i].match(/^[-*_]{3,}\s*$/) &&
      !lines[i].match(/^>\s/)
    ) {
      paraLines.push(lines[i])
      i++
    }
    if (paraLines.length > 0) {
      tokens.push({ type: 'paragraph', text: paraLines.join('\n') })
    }
  }

  return tokens
}

// ─── Inline Renderer ─────────────────────────────────────────────────────────

function InlineText({ text }: { text: string }) {
  const parts: React.ReactNode[] = []
  let i = 0
  let buf = ''
  let key = 0

  const flush = () => {
    if (buf) { parts.push(buf); buf = '' }
  }

  while (i < text.length) {
    // Bold **text**
    if (text[i] === '*' && text[i + 1] === '*') {
      const end = text.indexOf('**', i + 2)
      if (end !== -1) {
        flush()
        parts.push(<strong key={key++} className="font-semibold text-text">{text.slice(i + 2, end)}</strong>)
        i = end + 2; continue
      }
    }
    // Italic *text*
    if (text[i] === '*' && text[i + 1] !== '*') {
      const end = text.indexOf('*', i + 1)
      if (end !== -1 && end > i + 1) {
        flush()
        parts.push(<em key={key++} className="italic text-text-secondary">{text.slice(i + 1, end)}</em>)
        i = end + 1; continue
      }
    }
    // Inline code `code`
    if (text[i] === '`') {
      const end = text.indexOf('`', i + 1)
      if (end !== -1) {
        flush()
        parts.push(
          <code key={key++} className="font-mono text-[0.88em] text-accent bg-accent/8 px-1.5 py-0.5 rounded-md border border-accent/15">
            {text.slice(i + 1, end)}
          </code>
        )
        i = end + 1; continue
      }
    }
    // Link [text](url)
    if (text[i] === '[') {
      const cb = text.indexOf(']', i)
      if (cb !== -1 && text[cb + 1] === '(') {
        const cp = text.indexOf(')', cb + 2)
        if (cp !== -1) {
          flush()
          const linkText = text.slice(i + 1, cb)
          const url = text.slice(cb + 2, cp)
          const isExternal = url.startsWith('http')
          parts.push(
            <a key={key++} href={url} className="text-accent hover:text-accent-hover font-medium underline decoration-accent/30 underline-offset-2 hover:decoration-accent/60 transition-colors"
              target={isExternal ? '_blank' : undefined} rel={isExternal ? 'noopener noreferrer' : undefined}>
              {linkText}
            </a>
          )
          i = cp + 1; continue
        }
      }
    }
    buf += text[i]
    i++
  }
  flush()
  return <>{parts}</>
}

// ─── Code Block ──────────────────────────────────────────────────────────────

function ChatCodeBlock({ lang, text }: { lang: string; text: string }) {
  const [copied, setCopied] = useState(false)

  const copy = () => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className="my-3 rounded-lg border border-border overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 bg-surface-2 border-b border-border">
        <div className="flex items-center gap-1.5">
          <Terminal className="w-3 h-3 text-text-muted" />
          <span className="text-[10px] font-mono text-text-muted tracking-wider">
            {lang || 'code'}
          </span>
        </div>
        <button
          onClick={copy}
          className="flex items-center gap-1 text-[10px] text-text-muted hover:text-text transition-colors"
        >
          {copied ? <Check className="w-3 h-3 text-green" /> : <Copy className="w-3 h-3" />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre className="p-3 overflow-x-auto bg-surface text-[12px] font-mono text-text-secondary leading-[1.65]">
        <code>{text}</code>
      </pre>
    </div>
  )
}

// ─── Main Renderer ───────────────────────────────────────────────────────────

function RenderTokens({ tokens }: { tokens: Token[] }) {
  return (
    <>
      {tokens.map((token, idx) => {
        switch (token.type) {
          case 'h1':
            return (
              <h3 key={idx} className="text-[15px] font-bold text-text mt-4 mb-1.5">
                <InlineText text={token.text} />
              </h3>
            )
          case 'h2':
            return (
              <h4 key={idx} className="text-[14px] font-semibold text-text mt-3.5 mb-1.5">
                <InlineText text={token.text} />
              </h4>
            )
          case 'h3':
            return (
              <h5 key={idx} className="text-[13px] font-semibold text-text mt-3 mb-1">
                <InlineText text={token.text} />
              </h5>
            )
          case 'h4':
            return (
              <h6 key={idx} className="text-[13px] font-medium text-text-secondary mt-2.5 mb-1">
                <InlineText text={token.text} />
              </h6>
            )
          case 'hr':
            return <hr key={idx} className="my-3 border-border" />
          case 'code':
            return <ChatCodeBlock key={idx} lang={token.lang} text={token.text} />
          case 'table':
            return (
              <div key={idx} className="my-3 rounded-lg border border-border overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-[12px]">
                    <thead>
                      <tr className="bg-surface-2">
                        {token.headers.map((h, hi) => (
                          <th key={hi} className="px-3 py-2 text-left text-[11px] font-semibold text-text border-b border-border">
                            <InlineText text={h} />
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {token.rows.map((row, ri) => (
                        <tr key={ri} className="border-b border-border last:border-0">
                          {row.map((cell, ci) => (
                            <td key={ci} className="px-3 py-2 text-[12px] text-text-secondary">
                              <InlineText text={cell} />
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )
          case 'ul':
            return (
              <ul key={idx} className="my-2 space-y-1">
                {token.items.map((item, ii) => (
                  <li key={ii} className="flex items-start gap-2 text-[13px] text-text-secondary leading-relaxed">
                    <span className="mt-[7px] w-1 h-1 rounded-full bg-text-muted shrink-0" />
                    <span className="flex-1"><InlineText text={item} /></span>
                  </li>
                ))}
              </ul>
            )
          case 'ol':
            return (
              <ol key={idx} className="my-2 space-y-1.5">
                {token.items.map((item, ii) => (
                  <li key={ii} className="flex items-start gap-2 text-[13px] text-text-secondary leading-relaxed">
                    <span className="mt-[1px] w-5 h-5 rounded-md bg-surface-2 text-text-muted text-[10px] font-bold flex items-center justify-center shrink-0 border border-border">
                      {token.start + ii}
                    </span>
                    <span className="flex-1"><InlineText text={item} /></span>
                  </li>
                ))}
              </ol>
            )
          case 'paragraph':
            return (
              <p key={idx} className="my-1.5 text-[13px] text-text-secondary leading-relaxed">
                <InlineText text={token.text} />
              </p>
            )
          default:
            return null
        }
      })}
    </>
  )
}

// ─── Public Component ────────────────────────────────────────────────────────

export function MarkdownRenderer({ content }: { content: string }) {
  const tokens = tokenize(content)
  return (
    <div className="markdown-chat">
      <RenderTokens tokens={tokens} />
    </div>
  )
}

