                ))}
              </ul>
            )
          case 'ol':
            return (
              <ol key={idx} className="my-2 space-y-1.5">
                {token.items.map((item, ii) => (
                  <li key={ii} className="flex items-start gap-2 text-[13px] text-text-secondary leading-relaxed">
                    <span className="mt-[1px] w-5 h-5 rounded-md bg-surface-2 text-text-muted text-[10px] font-bold flex items-center justify-center shrink-0 border border-border">
                      {token.start + ii}
                    </span>
                    <span className="flex-1"><InlineText text={item} /></span>
                  </li>
                ))}
              </ol>
            )
          case 'paragraph':
            return (
              <p key={idx} className="my-1.5 text-[13px] text-text-secondary leading-relaxed">
                <InlineText text={token.text} />
              </p>
            )
          default:
            return null
        }
      })}
    </>
  )
}

// ─── Public Component ────────────────────────────────────────────────────────

export function MarkdownRenderer({ content }: { content: string }) {
  const tokens = tokenize(content)
  return (
    <div className="markdown-chat">
      <RenderTokens tokens={tokens} />
    </div>
  )
}

