import { useState, useRef, useEffect, useCallback } from 'react'
import {
  X, Send, Sparkles, Copy, Check, RefreshCw,
  History, Plus, Trash2, ChevronLeft, FileCode, CheckCircle, Bot, Download, Paperclip,
} from 'lucide-react'
import type { AiMessage, AiSession, AppContext } from '../lib/api'
import {
  streamAiChat, getAiHistory, getAiSession,
  saveAiSession, deleteAiSession, getAiContext, applyAiFile,
} from '../lib/api'
import { toast } from './Toast'

interface Props {
  open: boolean
  onClose: () => void
}

interface FileSuggestion {
  path: string
  content: string
  applied?: boolean
}

function buildContextPrompt(ctx: AppContext): string {
  let out = `## App Overview\n`

  out += `\n**Global CLAUDE.md:** ${ctx.globalClaudeMd.path}\n`
  out += `**Global agents directory:** ${ctx.globalAgentsDir}\n`

  if (ctx.globalAgents.length > 0) {
    out += `\n**Global Agents:**\n`
    for (const a of ctx.globalAgents) {
      out += `- ${a.name}: ${a.description || 'no description'} → ${a.path}\n`
    }
  }

  if (ctx.projects.length > 0) {
    out += `\n**Projects:**\n`
    for (const p of ctx.projects) {
      out += `\n### ${p.name}\n`
      out += `- Path: ${p.path}\n`
      out += `- Agents dir: ${p.agentsDir}\n`
      out += `- Commands dir: ${p.commandsDir}\n`
      out += `- Rules dir: ${p.rulesDir}\n`
      if (p.agents.length > 0)
        out += `- Agents: ${p.agents.map(a => a.name).join(', ')}\n`
      if (p.commands.length > 0)
        out += `- Commands: ${p.commands.map(c => c.name).join(', ')}\n`
      if (p.rules.length > 0)
        out += `- Rules: ${p.rules.map(r => r.name).join(', ')}\n`
    }
  }

  return out
}

function buildSystemPrompt(contextPrompt: string): string {
  return `You are an expert AI assistant with full access to the user's Claude Hub — a management dashboard for Claude Code agents, commands, rules, and CLAUDE.md files.

Your role: help the user create, improve, and manage all their Claude Code configurations.

CRITICAL — When writing any file, use the EXACT absolute paths from the context below:
- To create a global agent: use path like {globalAgentsDir}/agent-name.md
- To create a project agent: use path like {project.agentsDir}/agent-name.md
- To create a project command: use path like {project.commandsDir}/command-name.md
- To create a project rule: use path like {project.rulesDir}/rule-name.md
- File names must be lowercase, hyphen-separated (e.g. code-review.md)

Always output files using this exact format:
<file path="/the/exact/absolute/path/to/file.md">
file content here
</file>

For agents, always include frontmatter:
---
name: Agent Display Name
description: One line description
model: sonnet
---

Be practical and direct. Show complete files, never diffs.

${contextPrompt}`
}

function parseFileSuggestions(content: string): FileSuggestion[] {
  const results: FileSuggestion[] = []
  const regex = /<file path="([^"]+)">([\s\S]*?)<\/file>/g
  let match
  while ((match = regex.exec(content)) !== null) {
    results.push({ path: match[1], content: match[2].trim() })
  }
  return results
}

function formatTime(iso: string) {
  const d = new Date(iso)
  const now = new Date()
  const diffMs = now.getTime() - d.getTime()
  const diffMin = Math.floor(diffMs / 60000)
  if (diffMin < 1) return 'just now'
  if (diffMin < 60) return `${diffMin}m ago`
  const diffH = Math.floor(diffMin / 60)
  if (diffH < 24) return `${diffH}h ago`
  return d.toLocaleDateString()
}

interface SaveAgentState {
  content: string
  suggestedName: string
  key: string
}

export default function AiAssistant({ open, onClose }: Props) {
  const [sessionId, setSessionId] = useState<string | null>(null)
  const [messages, setMessages] = useState<AiMessage[]>([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [streamingText, setStreamingText] = useState('')
  const [error, setError] = useState('')
  const streamAbortRef = useRef<AbortController | null>(null)
  const [showHistory, setShowHistory] = useState(false)
  const [history, setHistory] = useState<AiSession[]>([])
  const [contextPrompt, setContextPrompt] = useState('')
  const [appCtx, setAppCtx] = useState<AppContext | null>(null)
  const [appliedFiles, setAppliedFiles] = useState<Record<string, boolean>>({})
  const [applyingFile, setApplyingFile] = useState<string | null>(null)
  const [copiedIdx, setCopiedIdx] = useState<number | null>(null)
  const [saveAgentModal, setSaveAgentModal] = useState<SaveAgentState | null>(null)
  const [saveAgentScope, setSaveAgentScope] = useState<string>('global')
  const [saveAgentName, setSaveAgentName] = useState('')
  const [savingAgent, setSavingAgent] = useState(false)
  const [attachedFile, setAttachedFile] = useState<{ name: string; content: string } | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const scrollInstantRef = useRef(false)

  const loadHistory = useCallback(async () => {
    try {
      const data = await getAiHistory()
      setHistory(data)
    } catch {}
  }, [])

  const loadContext = useCallback(async () => {
    if (contextPrompt) return
    try {
      const ctx = await getAiContext()
      setAppCtx(ctx)
      setContextPrompt(buildContextPrompt(ctx))
    } catch {}
  }, [contextPrompt])

  // Persist session to localStorage on every messages change
  useEffect(() => {
    if (messages.length > 0 && sessionId) {
      localStorage.setItem('claude-hub:active-session', sessionId)
      localStorage.setItem('claude-hub:active-messages', JSON.stringify(messages))
    }
  }, [messages, sessionId])

  // On first open: restore messages from localStorage immediately, then sync with server
  const restoredRef = useRef(false)
  useEffect(() => {
    if (open) {
      loadHistory()
      loadContext()

      if (!restoredRef.current && messages.length === 0) {
        restoredRef.current = true
        const savedId = localStorage.getItem('claude-hub:active-session')
        const savedMsgs = localStorage.getItem('claude-hub:active-messages')
        if (savedId && savedMsgs) {
          try {
            const parsed = JSON.parse(savedMsgs) as AiMessage[]
            if (parsed.length > 0) {
              scrollInstantRef.current = true
              setSessionId(savedId)
              setMessages(parsed)
              // Also sync with server in background (don't block UI)
              getAiSession(savedId).catch(() => {})
              return
            }
          } catch {}
        }
        if (savedId && !savedMsgs) {
          getAiSession(savedId)
            .then(session => {
              scrollInstantRef.current = true
              setSessionId(session.id)
              setMessages(session.messages)
            })
            .catch(() => localStorage.removeItem('claude-hub:active-session'))
          return
        }
      }

      if (messages.length > 0) scrollInstantRef.current = true
      setTimeout(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'instant' })
        inputRef.current?.focus()
      }, 80)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])

  useEffect(() => {
    const behavior = scrollInstantRef.current ? 'instant' : 'smooth'
    scrollInstantRef.current = false
    messagesEndRef.current?.scrollIntoView({ behavior })
  }, [messages])

  const persistSession = useCallback(async (msgs: AiMessage[], currentId: string | null) => {
    if (msgs.length === 0) return currentId
    const title = msgs[0].content.slice(0, 60) + (msgs[0].content.length > 60 ? '…' : '')
    const result = await saveAiSession({ id: currentId || undefined, title, messages: msgs })
    loadHistory()
    return result.id
  }, [loadHistory])

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (ev) => {
      const content = ev.target?.result as string
      setAttachedFile({ name: file.name, content })
    }
    reader.readAsText(file)
    e.target.value = '' // reset so same file can be re-attached
  }

  const send = async () => {
    const text = input.trim()
    if ((!text && !attachedFile) || loading) return

    // Build user message — include file content as a fenced block if attached
    const userContent = attachedFile
      ? `${text ? text + '\n\n' : ''}📎 **${attachedFile.name}**\n\`\`\`\n${attachedFile.content}\n\`\`\``
      : text

    const newMessages: AiMessage[] = [...messages, { role: 'user', content: userContent }]
    setMessages(newMessages)
    setInput('')
    setAttachedFile(null)
    setLoading(true)
    setStreamingText('')
    setError('')

    streamAbortRef.current = new AbortController()

    try {
      const sys = buildSystemPrompt(contextPrompt)
      const content = await streamAiChat(
        newMessages,
        sys,
        (chunk) => setStreamingText(prev => prev + chunk),
        streamAbortRef.current.signal,
      )
      setStreamingText('')
      const finalMessages = [...newMessages, { role: 'assistant' as const, content }]
      setMessages(finalMessages)
      const savedId = await persistSession(finalMessages, sessionId)
      if (!sessionId) setSessionId(savedId)
    } catch (err) {
      setStreamingText('')
      if (err instanceof Error && err.name === 'AbortError') {
        // User cancelled — keep messages as-is
      } else {
        setError(err instanceof Error ? err.message : 'Failed to get response')
      }
    } finally {
      setLoading(false)
      streamAbortRef.current = null
    }
  }

  const cancelStream = () => {
    streamAbortRef.current?.abort()
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      send()
    }
  }

  const openSession = async (id: string) => {
    try {
      const session = await getAiSession(id)
      scrollInstantRef.current = true
      setSessionId(session.id)
      setMessages(session.messages)
      setShowHistory(false)
      setError('')
      setAppliedFiles({})
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to load session')
    }
  }

  const exportChat = () => {
    if (messages.length === 0) return
    const title = messages[0].content.slice(0, 60).replace(/[^a-z0-9 ]/gi, '').trim() || 'chat'
    const md = messages.map(m =>
      `## ${m.role === 'user' ? 'You' : 'Claude'}\n\n${m.content}`
    ).join('\n\n---\n\n')
    const blob = new Blob([`# ${title}\n\n${md}`], { type: 'text/markdown' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${title.toLowerCase().replace(/\s+/g, '-')}.md`
    a.click()
    URL.revokeObjectURL(url)
  }

  const newChat = () => {
    setSessionId(null)
    setMessages([])
    setInput('')
    setError('')
    setStreamingText('')
    setShowHistory(false)
    setAppliedFiles({})
    localStorage.removeItem('claude-hub:active-session')
    localStorage.removeItem('claude-hub:active-messages')
  }

  const removeSession = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation()
    try {
      await deleteAiSession(id)
      loadHistory()
      if (sessionId === id) newChat()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete session')
    }
  }

  const openSaveAgent = (suggestion: FileSuggestion, key: string) => {
    // Extract name from frontmatter if available
    const nameMatch = suggestion.content.match(/^---[\s\S]*?^name:\s*(.+)$/m)
    const suggestedName = nameMatch
      ? nameMatch[1].trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '')
      : suggestion.path.split('/').pop()?.replace('.md', '') || 'my-agent'
    setSaveAgentModal({ content: suggestion.content, suggestedName, key })
    setSaveAgentName(suggestedName)
    setSaveAgentScope('global')
  }

  const handleSaveAgent = async () => {
    if (!saveAgentModal || !saveAgentName.trim() || !appCtx) return
    const slug = saveAgentName.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '')
    if (!slug) { toast('error', 'Invalid agent name'); return }

    let filePath: string
    if (saveAgentScope === 'global') {
      filePath = `${appCtx.globalAgentsDir}/${slug}.md`
    } else {
      const project = appCtx.projects.find(p => p.path === saveAgentScope)
      if (!project) { toast('error', 'Project not found'); return }
      filePath = `${project.agentsDir}/${slug}.md`
    }

    setSavingAgent(true)
    try {
      await applyAiFile(filePath, saveAgentModal.content)
      setAppliedFiles(prev => ({ ...prev, [saveAgentModal.key]: true }))
      toast('success', `Agent saved to ${saveAgentScope === 'global' ? 'Global' : appCtx.projects.find(p => p.path === saveAgentScope)?.name}`)
      window.dispatchEvent(new Event('claude-hub:file-applied'))
      setSaveAgentModal(null)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save agent')
    } finally {
      setSavingAgent(false)
    }
  }

  const handleApplyFile = async (suggestion: FileSuggestion, key: string) => {
    setApplyingFile(key)
    try {
      await applyAiFile(suggestion.path, suggestion.content)
      setAppliedFiles(prev => ({ ...prev, [key]: true }))
      toast('success', `Applied ${suggestion.path.split('/').pop()}`)
      window.dispatchEvent(new Event('claude-hub:file-applied'))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to apply file')
    } finally {
      setApplyingFile(null)
    }
  }

  const copyText = (text: string, idx: number) => {
    navigator.clipboard.writeText(text)
    setCopiedIdx(idx)
    setTimeout(() => setCopiedIdx(null), 2000)
  }

  // Render message content, showing apply buttons for file suggestions
  const renderMessage = (msg: AiMessage, idx: number) => {
    if (msg.role !== 'assistant') return null

    const suggestions = parseFileSuggestions(msg.content)
    // Replace <file ...> blocks with placeholders for display
    const displayContent = msg.content.replace(
      /<file path="[^"]+">[\s\S]*?<\/file>/g,
      ''
    ).trim()

    return (
      <div key={idx} className="flex gap-2.5 justify-start">
        <div className="w-6 h-6 rounded-md bg-purple-muted flex items-center justify-center shrink-0 mt-0.5">
          <Sparkles className="w-3.5 h-3.5 text-purple" />
        </div>
        <div className="max-w-[88%] space-y-2">
          {displayContent && (
            <div className="bg-surface-2 rounded-xl rounded-bl-sm px-3.5 py-2.5">
              <pre className="whitespace-pre-wrap font-sans text-[13px] leading-relaxed break-words text-text">
                {displayContent}
              </pre>
              <button
                onClick={() => copyText(msg.content, idx)}
                className="flex items-center gap-1.5 mt-2 text-[11px] text-text-muted hover:text-text transition-colors"
              >
                {copiedIdx === idx ? <Check className="w-3.5 h-3.5 text-green" /> : <Copy className="w-3.5 h-3.5" />}
                {copiedIdx === idx ? 'Copied' : 'Copy'}
              </button>
            </div>
          )}
          {suggestions.map((s, si) => {
            const key = `${idx}-${si}`
            const applied = appliedFiles[key]
            const applying = applyingFile === key
            const fileName = s.path.split('/').pop()
            const isAgent = /^---[\s\S]*?^name:/m.test(s.content)
            const existingAgentPaths = appCtx
              ? [
                  ...appCtx.globalAgents.map(a => a.path),
                  ...appCtx.projects.flatMap(p => p.agents.map(a => a.path)),
                ]
              : []
            const agentExists = isAgent && existingAgentPaths.some(p =>
              p === s.path || p.endsWith('/' + fileName)
            )
            const showSaveAgent = isAgent && !agentExists && !applied
            const showApply = !isAgent || agentExists
            return (
              <div key={key} className="bg-surface border border-border rounded-xl overflow-hidden">
                <div className="flex items-center justify-between px-3.5 py-2.5 bg-surface-2 border-b border-border">
                  <div className="flex items-center gap-2 min-w-0">
                    <FileCode className="w-3.5 h-3.5 text-accent shrink-0" />
                    <span className="text-[11px] font-mono text-text-secondary truncate">{fileName}</span>
                    {isAgent && (
                      <span className="text-[10px] bg-purple-muted text-purple px-1.5 py-0.5 rounded font-medium shrink-0">agent</span>
                    )}
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0 ml-2">
                    {showSaveAgent && (
                      <button
                        onClick={() => openSaveAgent(s, key)}
                        className="flex items-center gap-1 text-[11px] px-2.5 py-1 rounded-md font-medium bg-purple-muted text-purple hover:opacity-80 transition-all"
                      >
                        Save as Agent
                      </button>
                    )}
                    {(showApply || applied) && (
                      <button
                        onClick={() => handleApplyFile(s, key)}
                        disabled={applied || applying}
                        className={`flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-md font-medium transition-all ${
                          applied
                            ? 'bg-green-muted text-green cursor-default'
                            : 'bg-accent text-white hover:bg-accent-hover disabled:opacity-50'
                        }`}
                      >
                        {applying ? (
                          <RefreshCw className="w-3 h-3 animate-spin" />
                        ) : applied ? (
                          <><CheckCircle className="w-3 h-3" /> Applied</>
                        ) : (
                          'Apply to file'
                        )}
                      </button>
                    )}
                  </div>
                </div>
                <pre className="px-3.5 py-2.5 text-[11px] font-mono text-text-secondary overflow-x-auto max-h-40 whitespace-pre-wrap break-words leading-relaxed">
                  {s.content.slice(0, 800)}{s.content.length > 800 ? '\n…' : ''}
                </pre>
                <div className="px-3.5 pb-2">
                  <p className="text-[10px] font-mono text-text-muted truncate">{s.path}</p>
                </div>
              </div>
            )
          })}
        </div>
      </div>
    )
  }

  if (!open) return null

  return (
    <>
    <div className="fixed inset-0 z-50 flex">
      {/* Backdrop */}
      <div className="flex-1 bg-black/20" onClick={onClose} />

      {/* Panel */}
      <div className="w-[500px] bg-surface border-l border-border flex flex-col shadow-2xl h-full">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 rounded-lg bg-purple-muted flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-purple" />
            </div>
            <div>
              <p className="text-sm font-semibold">Claude AI</p>
              <p className="text-[11px] text-text-muted">Full app access</p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={newChat}
              title="New chat"
              className="p-1.5 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
            >
              <Plus className="w-4 h-4" />
            </button>
            <button
              onClick={exportChat}
              disabled={messages.length === 0}
              title="Export chat as Markdown"
              className="p-1.5 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            >
              <Download className="w-4 h-4" />
            </button>
            <button
              onClick={() => setShowHistory(!showHistory)}
              title="History"
              className={`p-1.5 rounded-lg transition-colors ${showHistory ? 'bg-accent-muted text-accent-hover' : 'text-text-muted hover:text-text hover:bg-surface-2'}`}
            >
              <History className="w-4 h-4" />
            </button>
            <button
              onClick={onClose}
              className="p-1.5 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* History Panel */}
        {showHistory && (
          <div className="border-b border-border bg-surface-2 flex-shrink-0 max-h-64 overflow-y-auto">
            <div className="px-4 py-3">
              <p className="text-[11px] font-semibold uppercase tracking-wider text-text-muted mb-2">
                Chat History ({history.length})
              </p>
              {history.length === 0 ? (
                <p className="text-xs text-text-muted py-2">No saved chats yet.</p>
              ) : (
                <div className="space-y-1">
                  {history.map((s) => (
                    <div
                      key={s.id}
                      onClick={() => openSession(s.id)}
                      className={`group flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-colors ${
                        sessionId === s.id
                          ? 'bg-accent-muted text-accent-hover'
                          : 'hover:bg-surface text-text-secondary hover:text-text'
                      }`}
                    >
                      <div className="min-w-0 flex-1">
                        <p className="text-[12px] font-medium truncate">{s.title}</p>
                        <p className="text-[10px] text-text-muted">
                          {formatTime(s.updatedAt)} · {s.messageCount ?? s.messages?.length ?? 0} messages
                        </p>
                      </div>
                      <button
                        onClick={(e) => removeSession(e, s.id)}
                        className="p-1 rounded opacity-0 group-hover:opacity-100 text-text-muted hover:text-red transition-all"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Messages */}
        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
          {messages.length === 0 && (
            <div className="text-center pt-8">
              <div className="w-14 h-14 rounded-2xl bg-purple-muted flex items-center justify-center mx-auto mb-4">
                <Sparkles className="w-7 h-7 text-purple" />
              </div>
              <p className="text-sm font-semibold text-text mb-1">Claude AI Assistant</p>
              <p className="text-xs text-text-muted mb-6 max-w-xs mx-auto">
                Full access to all your agents, commands, rules, and CLAUDE.md files. Ask me anything or tell me to make changes.
              </p>
              <div className="space-y-2 text-left max-w-sm mx-auto">
                {STARTER_PROMPTS.map((s) => (
                  <button
                    key={s}
                    onClick={() => setInput(s)}
                    className="w-full text-left text-xs px-3.5 py-2.5 rounded-xl bg-surface-2 text-text-secondary hover:bg-accent-muted hover:text-accent-hover transition-colors"
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((msg, idx) => {
            if (msg.role === 'assistant') {
              return renderMessage(msg, idx)
            }
            return (
              <div key={idx} className="flex justify-end">
                <div className="max-w-[85%] bg-accent text-white rounded-xl rounded-br-sm px-3.5 py-2.5">
                  <pre className="whitespace-pre-wrap font-sans text-[13px] leading-relaxed break-words">
                    {msg.content}
                  </pre>
                </div>
              </div>
            )
          })}

          {loading && (
            <div className="flex gap-2.5 justify-start">
              <div className="w-6 h-6 rounded-md bg-purple-muted flex items-center justify-center shrink-0 mt-0.5">
                <Sparkles className="w-3.5 h-3.5 text-purple animate-pulse" />
              </div>
              <div className="max-w-[88%]">
                {streamingText ? (
                  <div className="bg-surface-2 rounded-xl rounded-bl-sm px-3.5 py-2.5">
                    <pre className="whitespace-pre-wrap font-sans text-[13px] leading-relaxed break-words text-text">
                      {streamingText}
                    </pre>
                    <span className="inline-block w-0.5 h-3.5 bg-purple animate-pulse ml-0.5 align-middle" />
                  </div>
                ) : (
                  <div className="bg-surface-2 rounded-xl rounded-bl-sm px-3.5 py-3">
                    <div className="flex gap-1.5 items-center">
                      <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:0ms]" />
                      <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:150ms]" />
                      <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:300ms]" />
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {error && (
            <div className="bg-red-muted border border-red/20 rounded-xl px-4 py-3 text-sm text-red">
              {error}
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="px-4 py-4 border-t border-border shrink-0">
          {messages.length > 0 && (
            <button
              onClick={newChat}
              className="flex items-center gap-1.5 text-[11px] text-text-muted hover:text-text mb-3 transition-colors"
            >
              <ChevronLeft className="w-3.5 h-3.5" />
              New chat
            </button>
          )}
          {/* Attached file preview */}
          {attachedFile && (
            <div className="flex items-center gap-2 mb-2 px-3 py-2 bg-surface-2 border border-border rounded-lg">
              <Paperclip className="w-3.5 h-3.5 text-accent shrink-0" />
              <span className="text-xs font-mono text-text-secondary flex-1 truncate">{attachedFile.name}</span>
              <span className="text-[10px] text-text-muted">{(attachedFile.content.length / 1024).toFixed(1)}KB</span>
              <button onClick={() => setAttachedFile(null)} className="p-0.5 text-text-muted hover:text-red transition-colors">
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          <div className="flex gap-2 items-end">
            <input
              ref={fileInputRef}
              type="file"
              accept=".md,.txt,.ts,.tsx,.js,.jsx,.json,.css,.scss,.py,.go,.rs,.rb,.java,.html,.yaml,.yml,.toml,.sh,.env"
              onChange={handleFileUpload}
              className="hidden"
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              title="Attach file"
              className="p-2.5 rounded-xl text-text-muted hover:text-accent hover:bg-accent-muted disabled:opacity-30 transition-colors shrink-0 mb-0.5"
            >
              <Paperclip className="w-4 h-4" />
            </button>
            <textarea
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ask Claude to create, update, or explain anything…"
              rows={3}
              disabled={loading}
              className="flex-1 bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted disabled:opacity-60"
            />
            {loading ? (
              <button
                onClick={cancelStream}
                className="p-2.5 bg-red text-white rounded-xl hover:opacity-90 transition-colors shrink-0 mb-0.5"
                title="Stop generating"
              >
                <X className="w-4 h-4" />
              </button>
            ) : (
              <button
                onClick={send}
                disabled={!input.trim() && !attachedFile}
                className="p-2.5 bg-accent text-white rounded-xl hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors shrink-0 mb-0.5"
              >
                <Send className="w-4 h-4" />
              </button>
            )}
          </div>
          <p className="text-[11px] text-text-muted mt-2">
            Enter to send · Shift+Enter for new line · Changes are applied directly to files
          </p>
        </div>
      </div>
    </div>

    {/* Save as Agent Modal */}
    {saveAgentModal && (
      <div className="fixed inset-0 z-[60] flex items-center justify-center">
        <div className="absolute inset-0 bg-black/50" onClick={() => setSaveAgentModal(null)} />
        <div className="relative bg-surface border border-border rounded-2xl p-6 w-[400px] shadow-2xl">
          <h3 className="text-base font-semibold mb-4 flex items-center gap-2">
            <Bot className="w-5 h-5 text-purple" />
            Save Agent to Library
          </h3>
          <div className="space-y-3">
            <div>
              <label className="text-xs font-medium text-text-muted block mb-1.5">Agent file name</label>
              <input
                value={saveAgentName}
                onChange={e => setSaveAgentName(e.target.value.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, ''))}
                placeholder="agent-name"
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:border-accent/50"
                autoFocus
              />
            </div>
            <div>
              <label className="text-xs font-medium text-text-muted block mb-1.5">Save to</label>
              <select
                value={saveAgentScope}
                onChange={e => setSaveAgentScope(e.target.value)}
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              >
                <option value="global">Global (~/.claude/agents/)</option>
                {appCtx?.projects.map(p => (
                  <option key={p.path} value={p.path}>{p.name} (project)</option>
                ))}
              </select>
            </div>
          </div>
          <div className="flex gap-2 mt-5">
            <button
              onClick={() => setSaveAgentModal(null)}
              className="flex-1 px-4 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleSaveAgent}
              disabled={!saveAgentName.trim() || savingAgent}
              className="flex-1 px-4 py-2 text-sm font-medium bg-purple text-white rounded-lg hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {savingAgent ? 'Saving...' : 'Save Agent'}
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  )
}

const STARTER_PROMPTS = [
  'Show me all my agents and what they do',
  'Create a new global agent for code review',
  'Improve my global CLAUDE.md with better structure',
  'Write a /test command that runs tests intelligently',
  'What rules should I add for a TypeScript project?',
]

